import vue from "@vitejs/plugin-vue";
import { cpSync, createReadStream, existsSync, statSync } from "node:fs";
import { extname, resolve } from "node:path";
import { defaultClientConditions, defineConfig, type Plugin } from "vite";

const here = import.meta.dirname;

/// Where the glyph data of JSesh is, in this repository (`@jsesh/glyphs/data`, generated by
/// `../../gradlew -p ../.. :jseshJsExport:exportAll`). In your own project, copy it into `public/` instead,
/// or serve it from anywhere and give its URL to `JSeshPlugin`.
const GLYPH_DATA = resolve(here, "../../packages/glyphs/data");

const TYPES: Record<string, string> = { ".json": "application/json", ".ttf": "font/ttf", ".woff": "font/woff" };

/// Serves the glyph data under `/glyph-data/` (and copies it to `dist/` when building).
function glyphData(): Plugin {
  let outDir = "dist";
  return {
    name: "jsesh-glyph-data",
    configResolved: (config) => (outDir = resolve(config.root, config.build.outDir)),
    configureServer(server) {
      server.middlewares.use("/glyph-data", (req, res, next) => {
        const file = resolve(GLYPH_DATA, "." + decodeURIComponent((req.url ?? "/").split("?")[0]!));
        if (!file.startsWith(GLYPH_DATA) || !existsSync(file) || !statSync(file).isFile()) return next();
        res.setHeader("Content-Type", TYPES[extname(file)] ?? "application/octet-stream");
        createReadStream(file).pipe(res);
      });
    },
    closeBundle() {
      if (existsSync(GLYPH_DATA)) cpSync(GLYPH_DATA, resolve(outDir, "glyph-data"), { recursive: true });
    },
  };
}

export default defineConfig({
  // `base: "./"` lets the built application work from any folder of a web server.
  base: "./",
  // "source": use the TypeScript sources of the workspace packages (@jsesh/*), so no build is needed first.
  resolve: { conditions: ["source", ...defaultClientConditions] },
  plugins: [
    vue({
      // <jsesh-*> are Web Components, not Vue components (needed because @jsesh/vue is compiled here, from its sources).
      template: { compilerOptions: { isCustomElement: (tag) => tag.startsWith("jsesh-") } },
    }),
    glyphData(),
  ],
});
